<?php include __DIR__.'/admin_nav.php';$started=(int)($summary['started']??0);$finished=(int)($summary['finished']??0);$completion=$started?round($finished/$started*100,1):0; ?>
<section class="container admin-page"><div class="admin-title"><div><div class="eyebrow">ANALYTICS AND REPORTING</div><h1>Participation <em>Reports</em></h1><p>Performance by game, age group and the last 14 days. A unique registration does not mean a verified festival visitor.</p></div><a class="btn btn-primary" href="/admin/reports.csv">Download CSV ↓</a></div>
<div class="analysis-grid"><div class="analysis-card"><small>UNIQUE PLAYERS</small><strong><?=e($summary['players']??0)?></strong></div><div class="analysis-card"><small>TOTAL ATTEMPTS</small><strong><?=$started?></strong></div><div class="analysis-card"><small>COMPLETION RATE</small><strong><?=$completion?>%</strong></div><div class="analysis-card"><small>AVERAGE SCORE</small><strong><?=e($summary['average']??'—')?></strong></div></div>
<h2 class="report-section-title">Game Performance</h2><div class="admin-card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Game</th><th>Players</th><th>Attempts</th><th>Completed</th><th>Completion</th><th>Avg. Score</th><th>Accuracy</th><th>Avg. Time</th></tr></thead><tbody><?php foreach($report as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td class="numeric"><?=e($r['unique_players'])?></td><td class="numeric"><?=e($r['started'])?></td><td class="numeric"><?=e($r['finished']??0)?></td><td><div class="report-bar" title="<?=e($r['completion_rate']??0)?>%"><i style="width:<?=min(100,max(0,(float)($r['completion_rate']??0)))?>%"></i></div><small><?=e($r['completion_rate']??0)?>%</small></td><td class="numeric"><?=e($r['average']??'—')?></td><td class="numeric"><?=e($r['accuracy']??'—')?>%</td><td class="numeric"><?=isset($r['avg_seconds'])&&$r['avg_seconds']!==null?e(gmdate('i:s',(int)$r['avg_seconds'])):'—'?></td></tr><?php endforeach;?></tbody></table></div></div>
<h2 class="report-section-title">Age Groups</h2><div class="admin-card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Age</th><th>Players</th><th>Attempts</th><th>Completed</th><th>Average Score</th></tr></thead><tbody><?php foreach($ageReport as $r):?><tr><td><strong><?=e($r['label'])?></strong></td><td><?=e($r['unique_players'])?></td><td><?=e($r['started'])?></td><td><?=e($r['finished']??0)?></td><td><?=e($r['average']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div>
<h2 class="report-section-title">Last 14 Days</h2><div class="admin-card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Date (UTC)</th><th>Started</th><th>Completed</th><th>Completion</th></tr></thead><tbody><?php foreach($daily as $r):$rate=(int)$r['started']?round((int)$r['finished']/(int)$r['started']*100,1):0;?><tr><td><?=e($r['day'])?></td><td><?=e($r['started'])?></td><td><?=e($r['finished'])?></td><td><?=$rate?>%</td></tr><?php endforeach;?><?php if(!$daily):?><tr><td colspan="4">No attempts in the last 14 days yet.</td></tr><?php endif;?></tbody></table></div></div>
<div class="notice-block">📊 The detailed CSV contains player details, the four-digit code, age/gender, all game attempts, scores, times, questions, given/correct answers and explanations. Because it contains sensitive data, only authorised admins can download it.</div></section>
